/* Multi-song workspace. Active aliases keep the existing editor bindings stable. */
(function(root){'use strict';
const C=root.DCCore;
const DEFAULT_SETTINGS={theme:'neon',snap:2,layout:'dancecube',zoom:100,lineRatio:.72,follow:true,rate:1,noteSpeed:8,previewSpeedModel:'flight-2.5',separateSlides:false,showUseBackground:false,brightness:35,useBackground:true,auto:true,volume:65,metronome:false,waveform:true,frequency:true,sections:true,repeats:true,spectrum:true,onsets:true,freqLow:20,freqHigh:22050,waveGain:0,sensitivity:50,beatFormat:'both',gridColor:'#8d83aa',gridWidth:.7,gridOpacity:45,rulerSize:10,rulerMode:'bar',wheelDirection:'natural',comboPosition:'center',showFps:true,targetFps:120,preload:'off',hitFx:100,timelineZoom:100,timelinePan:0,mobileShortcuts:false,deviceMode:'auto',mobilePanel:'editor',exportFormat:'zip',...root.DCSettings?.DEFAULTS};
function sync(v){const item=v.songs?.find(s=>s.id===v.activeSongId);if(item){item.song=v.song;item.charts=v.charts;item.activeChartId=v.activeChartId;item.view=v.view;}return v;}
function activate(v,id){const item=v.songs.find(s=>s.id===id);if(!item)throw Error('歌曲不存在');v.activeSongId=id;v.song=item.song;v.charts=item.charts;v.activeChartId=item.activeChartId||item.charts[0].id;v.view=item.view||{bottomBeat:null,position:0};return item;}
function normalize(input){const v=C.clone(input);if(!['dc-studio-2','dc-studio-3'].includes(v.format))throw Error('不是 Studio 项目');if(!v.songs?.length){if(!Array.isArray(v.charts)||!v.charts.length)throw Error('项目缺少谱面');v.songs=[{id:C.uid(),song:v.song,charts:v.charts,activeChartId:v.activeChartId,view:v.view,assetPrefix:'',expanded:true,chartExpanded:{}}];v.activeSongId=v.songs[0].id;}else if(v.song&&v.charts)sync(v);
 for(const item of v.songs){item.id=String(item.id||C.uid());item.song={title:String(item.song?.title||'Untitled'),artist:String(item.song?.artist||''),...item.song};if(!Array.isArray(item.charts)||!item.charts.length)throw Error('歌曲缺少难度');item.charts=item.charts.map(C.validateChart);if(!item.charts.some(c=>c.id===item.activeChartId))item.activeChartId=item.charts[0].id;item.view={bottomBeat:null,position:0,...item.view};item.expanded=item.expanded!==false;item.chartExpanded=item.chartExpanded||{};item.assetPrefix=String(item.assetPrefix||'');}
 if(!v.songs.some(s=>s.id===v.activeSongId))v.activeSongId=v.songs[0].id;const oldVersion=v.format,previousSettings=v.settings||{},activeItem=v.songs.find(s=>s.id===v.activeSongId)||v.songs[0],active=activeItem.charts.find(c=>c.id===activeItem.activeChartId)||activeItem.charts[0],legacySpeed=active.mode==='show'?previousSettings.showSpeed??previousSettings.noteSpeed:previousSettings.noteSpeed,legacyFlight={6:.38,7:.32,8:.30,9:.28},oldSpeed=previousSettings.previewSpeedModel==='flight-2.5'?previousSettings.noteSpeed:Number(legacySpeed)>0?active.mode==='show'?2.5/(legacyFlight[legacySpeed]||.3):Number(legacySpeed)*2.5:undefined;v.format='dc-studio-3';v.settings={...DEFAULT_SETTINGS,...previousSettings,noteSpeed:C.clamp(Math.round((Number(oldSpeed)||DEFAULT_SETTINGS.noteSpeed)*10)/10,1,12),previewSpeedModel:'flight-2.5'};delete v.settings.showSpeed;if(oldVersion!=='dc-studio-3')v.settings.zoom=C.clamp((+v.settings.zoom||100)/2,1,400);v.settings.zoom=C.clamp(+v.settings.zoom||100,1,400);v.settings.timelineZoom=C.clamp(+v.settings.timelineZoom||100,100,2000);if(!C.LAYOUTS[v.settings.layout])v.settings.layout='dancecube';if(root.DCSettings){if(!previousSettings.lineStyles&&['gridColor','gridWidth','gridOpacity'].some(k=>k in previousSettings))delete v.settings.lineStyles;v.settings=root.DCSettings.normalize(v.settings);}activate(v,v.activeSongId);return v;}
function timestamp(date=new Date()){const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',minute:'2-digit',second:'2-digit'}).formatToParts(date).map(p=>[p.type,p.value]));return p.year+p.month+p.day+p.minute+p.second;}
function fileName(name){return String(name||'Untitled').replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').slice(0,80);}
function mergeSongs(input,assets,targetId,sourceId){if(targetId===sourceId)throw Error('请选择另一首本地歌曲');const next=C.clone(input);sync(next);const target=next.songs.find(s=>s.id===targetId),source=next.songs.find(s=>s.id===sourceId);if(!target||!source)throw Error('歌曲已不存在');const folder='merged-'+source.id+'/',sourceAssets=new Map([...assets].filter(([key])=>key.startsWith(source.assetPrefix)&&(!source.assetPrefix?!next.songs.some(s=>s.assetPrefix&&key.startsWith(s.assetPrefix)):true)).map(([key,value])=>[key.slice(source.assetPrefix.length),value])),media=new Map(assets);
for(const[name,value]of sourceAssets){media.set(target.assetPrefix+folder+name,value);media.delete(source.assetPrefix+name);}const used=new Set(target.charts.map(c=>c.id));for(const ch of source.charts){if(used.has(ch.id))ch.id=C.uid();used.add(ch.id);const directory=ch.filename?.includes('/')?ch.filename.slice(0,ch.filename.lastIndexOf('/')+1):'';for(const key of ['audioName','backgroundName','titleImage','txtFile','svFile'])if(ch[key]){const name=sourceAssets.has(ch[key])?ch[key]:directory+ch[key];ch[key]=folder+name;}ch.filename=folder+(ch.filename||ch.id+'.mc');target.charts.push(ch);}target.chartExpanded={...target.chartExpanded,...source.chartExpanded};target.expanded=true;next.songs=next.songs.filter(s=>s.id!==sourceId);activate(next,targetId);return{project:normalize(next),assets:media};}
root.DCProject={DEFAULT_SETTINGS,mergeSongs,sync,activate,normalize,timestamp,fileName};
})(typeof window==='undefined'?globalThis:window);
